function kb.relicWorth(Fib,Gib)
local Hib=Gib._unique_item_data and Gib._unique_item_data._unique_relic_data
if not Hib then
return 0
end
local Iib=N.Items[Gib.item_id]or{}
local Jib,Kib=V.types(Fib.unit_id)
if Iib.main_damage_type and Iib.main_damage_type~=L_e[3156]and Iib.main_damage_type~=Kib then
return 0
end
local Lib,Mib=0,0
for Nib,Oib in pairs(Hib._core_damage_type_buffs or{})do
if Jib[Oib.damage_type]then
Lib=Lib+(tonumber(Oib.mul)or 0)+(tonumber(Oib.add_upg)or 0)*0.01+(tonumber(Oib.pen)or 0)*0.001
Mib=Mib+(tonumber(Oib.crit)or 0)
end
end
Lib=Lib+Mib*0.5
local Pib=V.rows(Fib.unit_id)
local Qib=Pib and Pib[Pib.max]
local Rib=(Qib and tonumber(Qib.cd)or 0)*V.mult(Fib,L_e[2893])
for Sib,Tib in pairs(Hib._unique_relic_effects or{})do
local Uib=type(Tib.params)==L_e[2442]and Tib.params or{}
if Tib.id==L_e[3573]then
local Vib=math.min(1,(tonumber(Uib.extra_damage)or 0)*Rib/math.max(1,tonumber(Uib.time_interval)or 40))
local Wib=V.DRONES and V.DRONES[Fib.unit_id]
if Wib and Wib.late and Rib>0 then
local Xib=1/Rib
Vib=Vib*Xib/(Xib+(tonumber(Wib.max)or 0)*(tonumber(Wib.late.dmg)or 0)*(tonumber(Wib.hits)or 1)/math.max(0.1,tonumber(Wib.late.cd)or 4))
end
Lib=Lib+Vib
elseif Tib.id==L_e[3574]then
Lib=Lib+(tonumber(Uib.dmg_buff)or 0)*0.25
elseif Tib.id==L_e[3575]then
Lib=Lib+(tonumber(Uib.dmg_buff)or 0)*Mib
elseif Tib.id==L_e[3576]then
if Jib.magic then
Lib=0
else
Lib=Lib+(tonumber(Uib.dmg_buff)or 0)*0.3
end
elseif Tib.id==L_e[3577]then
if Jib.water_damage then
Lib=Lib+0.05
end
elseif Tib.id==L_e[2594]then
local Yib=tonumber(Uib.duration_buff)or tonumber(type(Tib.static_params)==L_e[2442]and Tib.static_params.duration_buff)or 2
local Zib,_ib=pcall(V.attackInfo,Qib and Qib.atk,Qib and Qib.range)
local ajb,bjb=Zib and tonumber(_ib.burn)or 0,Zib and tonumber(_ib.dot)or 0
if ajb<=0 then
local cjb,djb=pcall(pb.model,Fib.unit_id,Zib and _ib or nil,Qib)
if cjb and type(djb)==L_e[2442]and(tonumber(djb.burnDot)or 0)>0 then
ajb,bjb=djb.burnDot,bjb+(tonumber(djb.dot)or 0)
end
end
Lib=Lib+ajb*math.max(0,Yib-1)/(1+bjb)
end
end
return Lib
end
function kb.relicPlan()
