zjb=true
end
end
local Cjb=not zjb and ejb.inventory:get_item_by_uuid(ljb.u._equipped_relic)
if Cjb then
table.insert(ujb,{it=Cjb,w=kb.relicWorth(ljb.u,Cjb)*njb*100})
