function kb.xpGuess(Dlb)
local Elb=Dlb.level and N.Levels[Dlb.level]
if not Elb then
return 0
end
local Flb=math.min(9,tonumber(Elb.story_world_rank)or tonumber(Dlb.rank)or 9)
local Glb=tonumber(Elb.story_level_rank)or 6
local Hlb=(Dlb.kind==L_e[2491]and 1.5 or 1)*(Flb>5 and 2 or 1)
local Ilb=2.1564^(Flb-1)*(40+10*Glb)/Hlb
if Dlb.kind==L_e[2467]then
Ilb=3*30*2.1564^(Flb-1)/Hlb
end
local Jlb=Flb>=9 and 0.3 or(Flb>=7 and 0.5 or 1)
return Ilb*Jlb*6
end
function kb.modeBonus(Klb)
