if Llb<=0 then
return 0
end
local Mlb=P.modes and P.modes[Klb.key]
local Nlb=tonumber(Mlb and Mlb.xp)or kb.xpGuess(Klb)
local Olb=Nlb*Llb
if Olb<1 then
return 0
end
return Olb,string.format(L_e[3594],U.fmt(Nlb),math.floor(Olb+0.5))
end
function kb.xpSettle()
