end
local Wlb=W.rec(Plb.key)
Wlb.xp=Wlb.xp and(Wlb.xp+(Rlb-Wlb.xp)*0.3)or Rlb
if Rlb>0 then
F.log(2,kb.LOG,string.format(L_e[3595],Plb.key,U.fmt(Rlb)))
