function kb.feedPlan(Ylb)
local Zlb=V.trait(Ylb)
local _lb=Zlb==L_e[3596]and 1.5 or 1
local amb=math.max(0,kb.xpFor(Ylb.unit_id,kb.cap(Ylb))-(tonumber(Ylb.xp)or 0))
local bmb,cmb,dmb={},0,0
for emb,fmb in ipairs(kb.foodHeld())do
local gmb=fmb.xp*_lb
local hmb=math.min(fmb.n,math.floor((amb-cmb)/math.max(1,gmb)))
if hmb>0 then
bmb[fmb.id]=hmb
cmb=cmb+hmb*gmb
dmb=dmb+hmb
end
end
return{feed=bmb,planned=cmb,n=dmb}
end
function kb.run(imb)
local jmb=N.session()
local kmb=jmb and jmb.collection:get_unit_by_uuid(imb.uuid)
if not kmb then
return
end
if imb.kind==L_e[3590]then
local lmb=kb.feedPlan(kmb)
local mmb,nmb,omb=lmb.feed,lmb.planned,lmb.n
if omb==0 then
P.str.feedNote=imb.name..L_e[3597]
return
end
local pmb,qmb=tonumber(kmb.xp)or 0,kb.level(kmb)
local rmb,smb=F.request(L_e[3590],L_e[3598],imb.uuid,mmb)
local tmb=U.now()
while U.now()-tmb<4 and(tonumber((jmb.collection:get_unit_by_uuid(imb.uuid)or kmb).xp)or 0)<=pmb do
task.wait(0.25)
end
local umb=jmb.collection:get_unit_by_uuid(imb.uuid)or kmb
local vmb=(tonumber(umb.xp)or 0)-pmb
if vmb>0 then
local wmb=kb.level(umb)
local xmb=wmb>qmb and string.format(L_e[3592],qmb,wmb)or string.format(L_e[3593],qmb)
cb.add(string.format(L_e[3599],omb,imb.name),omb,L_e[3600],string.format(L_e[3601],U.fmt(vmb),xmb))
kb.note(string.format(L_e[3602],imb.name,omb,U.fmt(vmb),xmb,math.abs(vmb-nmb)>nmb*0.1 and string.format(L_e[3603],U.fmt(nmb))or L_e[1359]))
else
kb.note(string.format(L_e[3604],imb.name,tostring(rmb and smb or L_e[2999])))
F.backoff(L_e[3590],600)
end
end
end
