if not Hnb then
return false,L_e[3648]
end
local Inb,Jnb=0,{}
for Knb,Lnb in pairs(Gnb.profile_data.collection.owned_units)do
if Lnb.unit_id==Enb.to then
Inb=Inb+1
Jnb[Knb]=true
end
end
local Mnb,Nnb=F.request(L_e[2550],L_e[3649],Enb.uuid)
task.wait(2)
local Onb=Gnb.collection:get_unit_by_uuid(Enb.uuid)
local Pnb=0
for Qnb,Rnb in pairs(Gnb.profile_data.collection.owned_units)do
if Rnb.unit_id==Enb.to then
Pnb=Pnb+1
if not Jnb[Qnb]then
if O.fuseXpUnit==Enb.uuid then
O.fuseXpUnit,O.fuseXpId=Qnb,Enb.to
F.saveSoon()
end
end
end
end
if Pnb>Inb then
local Snb={}
