end
local Xnb=string.format(L_e[3652],V.name(Enb.from),V.name(Enb.to),U.fmt(Enb.scoreFrom or 0),U.fmt(Enb.scoreTo or 0))
cb.add(L_e[3653]..Xnb,1,L_e[3654],(Fnb or L_e[3655])..(#Snb>0 and(L_e[3656]..table.concat(Snb,L_e[2566]))or L_e[1359]))
F.log(1,L_e[3657],Xnb..L_e[3658]..(Fnb or L_e[3655])..(#Snb>0 and(L_e[3656]..table.concat(Snb,L_e[2566]))or L_e[1359]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(Enb.to)..L_e[3659]
end
F.log(1,L_e[3657],L_e[3660]..V.name(Enb.from)..L_e[3183]..tostring(Nnb)..L_e[3661]..tostring(Onb and Onb.unit_id))
