function eb.upgradeGain(WOb,XOb,YOb,ZOb,_Ob,aPb)
local bPb,cPb=XOb[YOb],XOb[YOb+1]
local dPb=(bPb.cd>0 and bPb.damage/bPb.cd or 0)
local ePb=(cPb.cd>0 and cPb.damage/cPb.cd or 0)*V.aoeUp(cPb.atk,cPb.range)/math.max(0.3,V.aoeUp(bPb.atk,bPb.range))
local fPb=dPb>0 and WOb*(ePb/dPb-1)or(aPb or 0)
local gPb=XOb[YOb+2]
if gPb and YOb+1<XOb.max and gPb.cd>0 and cPb.cd>0 and dPb>0 then
local hPb=WOb*((gPb.damage/gPb.cd)/dPb-1)
local iPb=ZOb+gPb.cost*_Ob
if hPb/iPb>fPb/ZOb then
fPb=fPb+(hPb/iPb*ZOb-fPb)*0.5
end
end
local jPb=(cPb.range or 0)>(bPb.range or 0)and(1+((cPb.range-bPb.range)/math.max(1,bPb.range)))or 1
return math.max(0,fPb)*jPb
end
function eb.dpsFor(kPb,lPb)
if lPb<=0 then
return 0
end
local mPb={}
for nPb,oPb in ipairs(kPb)do
if not oPb.farm and not oPb.grif and oPb.gain>0 then
table.insert(mPb,oPb)
end
end
table.sort(mPb,function(pPb,qPb)
return pPb.gain/pPb.cost>qPb.gain/qPb.cost
end)
local rPb,sPb=0,0
for tPb,uPb in ipairs(mPb)do
if lPb<=0 then
break
end
sPb=uPb.gain/uPb.cost
local vPb=math.min(1,lPb/uPb.cost)
rPb=rPb+uPb.gain*vPb
lPb=lPb-uPb.cost*vPb
end
return rPb+math.max(0,lPb)*sPb*0.7
end
function eb.shieldDps(wPb,xPb,yPb,zPb,APb,BPb,CPb)
if(zPb or 0)<=0 or(wPb or 0)<=0 or(APb or 0)<=0 then
return wPb or 0
end
xPb,yPb,BPb=math.max(0.3,xPb or 2),math.max(1,yPb or 1),BPb or 1
local DPb=wPb*BPb*xPb/yPb
return APb*yPb/((zPb/math.max(1,CPb or 1)+math.max(1,APb/DPb))*xPb)/BPb
end
function eb.shieldGain(EPb,FPb,GPb,HPb,IPb,JPb,KPb,LPb)
local MPb,NPb=V.attackInfo(FPb.atk,FPb.range),V.attackInfo(HPb.atk,HPb.range)
local OPb=eb.shieldDps(EPb,(tonumber(FPb.cd)or 2)*(KPb or 1),MPb.n,IPb,JPb,LPb,MPb.hits)
local PPb=eb.shieldDps(GPb,(tonumber(HPb.cd)or 2)*(KPb or 1),NPb.n,IPb,JPb,LPb,NPb.hits)
local QPb=math.max(0,((tonumber(HPb.range)or 0)-(tonumber(FPb.range)or 0))/math.max(1,tonumber(FPb.range)or 1))
return math.max(0,PPb-OPb)+OPb*QPb
end
function eb.shieldWork(RPb,SPb,TPb,UPb,VPb,WPb,XPb,YPb,ZPb)
if(UPb or 0)<=0 then
return 0
end
local _Pb=3*UPb*(VPb or 1)/math.max(1,WPb or 20)
if(TPb or 0)>=_Pb then
