if not N.PC.is_valid_raycast_hit(OMc.Instance,MMc)then
return nil
end
local PMc=OMc.Position
if bb.blockedSpot(PMc)then
return nil
end
local QMc=(tonumber(MMc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(QMc*2,2.5,QMc*2)
bb.probe.CFrame=CFrame.new(PMc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local RMc=U.flat(PMc)
local SMc=bb.grifZone
if SMc and type(MMc)==L_e[2442]and MMc.id~=V.GRIF.egg and not V.sacFodder(MMc.id)and(RMc-SMc.p).Magnitude<=SMc.r+1.5 then
return nil
end
for TMc,UMc in ipairs(bb.mine or{})do
local VMc=UMc:FindFirstChild(L_e[4758])
local WMc=VMc and VMc.Position or UMc:GetPivot().Position
local XMc=VMc and math.max(VMc.Size.X,VMc.Size.Z)/2 or 1.5
if(RMc-U.flat(WMc)).Magnitude<QMc+XMc then
return nil
end
end
if not NMc then
for YMc,ZMc in ipairs(bb.blockers())do
if(RMc-ZMc.p).Magnitude<QMc+ZMc.r then
return nil
end
end
end
return PMc
end
function bb.buildCandidates()
bb.cands={}
local _Mc={}
for aNc=1,#bb.samples,3 do
local bNc=bb.samples[aNc]
local cNc=bb.samples[math.min(#bb.samples,aNc+1)]
local dNc=U.flat(cNc.pos-bNc.pos)
if dNc.Magnitude<0.01 then
dNc=Vector3 .new(1,0,0)
end
dNc=dNc.Unit
local eNc=Vector3 .new(-dNc.Z,0,dNc.X)
for fNc,gNc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for hNc,iNc in ipairs({1,-1})do
local jNc=bNc.pos+eNc*gNc*iNc
local kNc=string.format(L_e[4755],math.floor(jNc.X/1.5),math.floor(jNc.Z/1.5))
if not _Mc[kNc]then
_Mc[kNc]=true
table.insert(bb.cands,jNc)
end
end
end
end
end
function bb.coverage(lNc,mNc)
local nNc={}
for oNc,pNc in ipairs(lNc)do
local qNc=pNc._stats
if not V.isFarm(qNc.id.Value)and qNc:FindFirstChild(L_e[2710])then
table.insert(nNc,{p=U.flat(pNc:GetPivot().Position),r=qNc.range.Value*(V.SUMMONER[qNc.id.Value]and V.SUMMONER[qNc.id.Value].reach or 1),air=bb.canAir(pNc)})
end
end
local rNc,sNc=0,0
if#nNc>0 then
for tNc,uNc in ipairs(bb.samples)do
if uNc.prog>sNc then
local vNc=U.flat(uNc.pos)
for wNc,xNc in ipairs(nNc)do
if(vNc-xNc.p).Magnitude<=xNc.r then
if uNc.prog>rNc then
rNc=uNc.prog
end
if xNc.air then
sNc=uNc.prog
break
end
end
end
end
end
end
local yNc,zNc={},bb.laneCount
if zNc and zNc.n>=2 and#nNc>0 then
local ANc={}
for BNc,CNc in ipairs(bb.samples)do
local DNc=U.flat(CNc.pos)
for ENc,FNc in ipairs(nNc)do
if(DNc-FNc.p).Magnitude<=FNc.r then
local GNc=tostring(CNc.lane)
ANc[GNc]=(ANc[GNc]or 0)+1
if CNc.prog>(yNc[GNc]or 0)then
yNc[GNc]=CNc.prog
end
break
end
end
end
local HNc,INc={},0
for JNc,KNc in pairs(zNc.by)do
HNc[JNc]=(ANc[JNc]or 0)/math.max(1,KNc)
INc=math.max(INc,HNc[JNc])
end
bb.laneW={}
for LNc,MNc in pairs(zNc.by)do
bb.laneW[LNc]=(zNc.avg/math.max(1,MNc))*(1+1.5*(INc>0 and(1-HNc[LNc]/INc)or 0))
end
bb.laneFrac=HNc
else
bb.laneW,bb.laneFrac=nil,nil
end
local NNc,ONc,PNc
if#nNc>0 then
for QNc,RNc in ipairs(mNc)do
local SNc=(bb.laneW and RNc.lane)and(yNc[tostring(RNc.lane)]or 0)or rNc
if RNc.hp>0 and RNc.prog>SNc+0.02 and RNc.prog>(NNc or 0)then
NNc,PNc=RNc.prog,bb.laneW and RNc.lane or nil
end
if RNc.hp>0 and RNc.fly and RNc.prog>sNc+0.02 then
ONc=true
end
end
end
local TNc= #nNc>0 and(bb.pressure or 0)>=rNc-0.08
local UNc
if#nNc>0 and bb.killZone()then
local VNc= #nNc
for WNc,XNc in ipairs(nNc)do
VNc=VNc+XNc.r+XNc.p.X*0.01+XNc.p.Z*0.001
end
if bb._boxSig~=VNc then
local YNc={}
for ZNc,_Nc in ipairs(bb.samples)do
local aOc,bOc=U.flat(_Nc.pos),0
for cOc,dOc in ipairs(nNc)do
if(aOc-dOc.p).Magnitude<=dOc.r then
bOc=bOc+1
end
end
if bOc>0 then
table.insert(YNc,{p=_Nc.prog,w=bOc})
end
end
bb._boxSig,bb._boxFrom=VNc,eb.boxFrom(YNc)
end
UNc=bb._boxFrom
end
return{covEnd=rNc,airEnd=sNc,leak=NNc,leakLane=PNc,covL=yNc,airLeak=ONc,push=TNc,units= #nNc,boxFrom=UNc}
end
function bb.needLastLine(eOc)
