V._airFrom={}
function V.airFrom(sOc)
local tOc=V._airFrom[sOc]
if tOc~=nil then
return tOc or nil
end
local uOc=N.Units[sOc]
if uOc and(uOc.hill_unit or uOc.hybrid_placement or V.SUMMONER[sOc])then
V._airFrom[sOc]=0
return 0
end
local vOc=V.rows(sOc)
if not(vOc and vOc.max)then
return bb.cardAir(sOc)and 0 or nil
end
local wOc=false
for xOc=0,vOc.max do
local yOc=vOc[xOc]and vOc[xOc].atk
if yOc and N.Attacks[yOc]and N.Attacks[yOc].targets_flying then
wOc=xOc
break
end
end
if wOc==false and bb.cardAir(sOc)then
wOc=0
end
V._airFrom[sOc]=wOc
return wOc or nil
end
function bb.cardAir(zOc)
local AOc=N.Units[zOc]
if not AOc then
return false
end
if AOc.hill_unit or AOc.hybrid_placement then
return true
end
local BOc=V.field(zOc,L_e[2559])or V.field(zOc,L_e[2558])
return BOc and N.Attacks[BOc]and N.Attacks[BOc].targets_flying and true or false
end
function bb.airShare()
local COc,DOc=0,0
for EOc,FOc in ipairs(bb.mine or{})do
local GOc=FOc._stats.id.Value
if not V.isFarm(GOc)then
local HOc,IOc=pcall(bb.liveDps,FOc,GOc)
IOc=HOc and IOc or 0
COc=COc+IOc
if bb.canAir(FOc)then
DOc=DOc+IOc
end
end
end
return COc>0 and DOc/COc or 0
end
