function bb.cover(KPc,LPc,MPc,NPc,OPc)
local PPc=0
local QPc=U.flat(KPc)
local RPc=MPc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local SPc=bb.laneW
for TPc,UPc in ipairs(OPc and bb.samples or bb.hurtSamples())do
if(U.flat(UPc.pos)-QPc).Magnitude<=LPc then
local VPc=1
if RPc then
VPc=0.15+0.85*(tonumber(RPc[math.min(gb.BINS,math.floor(UPc.prog*gb.BINS)+1)])or 0)
end
if SPc then
VPc=VPc*(SPc[tostring(UPc.lane)]or 1)
end
if NPc then
if NPc.leak and UPc.prog>=NPc.leak-0.01 and(not NPc.leakLane or tostring(UPc.lane)==NPc.leakLane)then
VPc=VPc+3
elseif NPc.push and UPc.prog>NPc.covEnd then
VPc=VPc+0.6
end
end
PPc=PPc+VPc
end
end
return PPc
end
