if eQc and(V.bleeds(eQc)or 99)<=fQc then
aQc=true
break
end
end
return eb.bleedShare(eb.bleedGain(ZPc,bb.hpAlive or 0,bb.coming,aQc),_Pc,XPc,YPc)
end
