bb.REAL_WIN=75
function bb.realK(Nkd)
local Okd=bb.realC
local Pkd=U.now()
if not Okd then
Okd={t=0,k={},snaps={},seen={}}
bb.realC=Okd
end
if Pkd-Okd.t>=5 then
Okd.t=Pkd
Okd.k={}
local Qkd,Rkd,Skd=pcall(bb.damageShares)
local Tkd={}
if Qkd and type(Rkd)==L_e[2442]and(Skd or 0)>0 then
for Ukd,Vkd in pairs(Rkd)do
Tkd[Ukd]=Vkd*Skd
end
end
local Wkd,Xkd={},0
for Ykd,Zkd in ipairs(bb.mine or{})do
local _kd=Zkd:FindFirstChild(L_e[2514])
local ald=_kd and _kd:FindFirstChild(L_e[2835])and _kd.id.Value
if ald and not V.isFarm(ald)then
local bld,cld=pcall(bb.liveDps,Zkd,ald)
cld=bld and tonumber(cld)or 0
Wkd[ald]=(Wkd[ald]or 0)+cld
Xkd=Xkd+cld
Okd.seen[ald]=Okd.seen[ald]or Pkd
end
end
table.insert(Okd.snaps,{t=Pkd,abs=Tkd})
while#Okd.snaps>1 and Pkd-Okd.snaps[2].t>=bb.REAL_WIN do
table.remove(Okd.snaps,1)
end
local dld=Okd.snaps[1]
if Pkd-dld.t>=20 and Xkd>0 then
local eld,fld={},0
for gld in pairs(Wkd)do
local hld=math.max(0,(Tkd[gld]or 0)-(dld.abs[gld]or 0))
eld[gld]=hld
fld=fld+hld
end
if fld>0 then
local ild
for jld,kld in pairs(Wkd)do
if Pkd-Okd.seen[jld]>=eb.REAL_AGE then
local lld=eb.realK(eld[jld]/fld,kld/Xkd,eb.REAL_AGE)
if not ild or lld<ild then
ild=lld
end
end
end
for mld,nld in pairs(Wkd)do
Okd.k[mld]=eb.realK(eld[mld]/fld,nld/Xkd,Pkd-Okd.seen[mld],ild)
end
end
end
end
return Okd.k[Nkd]or 1
end
