local vEd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(uEd.n)or 0))))
uEd.eff=(tonumber(uEd.n)or 0)==0 and tEd or((tonumber(uEd.eff)or tEd)+(tEd-(tonumber(uEd.eff)or tEd))*vEd)
uEd.n=(tonumber(uEd.n)or 0)+1
rEd[sEd]=uEd
end
rEd._at=os.time()
P.mapLearn[qEd]=rEd
