bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(HKd,IKd)
local JKd=(IKd.t or 0)-(HKd.t or 0)
if JKd<bb.BASE_WIN-1 then
return false
end
local KKd=((tonumber(HKd.base)or 0)-(tonumber(IKd.base)or 0))/JKd
if KKd<=0 or(tonumber(IKd.base)or 0)<=0 then
return false
end
local LKd=IKd.base/KKd
local MKd,NKd=0,0
local OKd,PKd=HKd.foes or{},IKd.foes or{}
for QKd,RKd in pairs(PKd)do
if RKd.prog>=bb.BASE_END then
MKd=MKd+RKd.hp
local SKd=OKd[QKd]
if SKd then
NKd=NKd+math.max(0,SKd.hp-RKd.hp)
end
end
end
for TKd,UKd in pairs(OKd)do
if UKd.prog>=bb.BASE_END and not PKd[TKd]then
NKd=NKd+UKd.hp
end
end
if MKd<=0 then
return false
end
local VKd=NKd/JKd
local WKd=VKd>0 and MKd/VKd or math.huge
local XKd={baseTime=LKd,loss=KKd,atEnd=MKd,rate=VKd,killTime=WKd}
return LKd<bb.BASE_SOON and WKd>LKd*bb.BASE_MARGIN,XKd
end
